		void OnActionMenuItemPopup(object sender, EventArgs e)
		{
			var pick = Pick;
			AllocatePackageLabelsMenuItem.Visible = !pick.WP_IsCartonised;
			CancelPackageLabelsMenuItem.Visible = pick.WP_IsCartonised;

			AllocatePackageLabelsMenuItem.Enabled = pick.CanAllocatePackageLabels;
			CancelPackageLabelsMenuItem.Enabled = pick.CanCancelPackageLabelAllocations;

			PrintAllPackageLabelsMenuItem.SetMenuItemCaption();
			PrintAllPackageLabelsWithoutSeparatorLabelsMenuItem.SetMenuItemCaption();
		}

		void AllocatePackageLabels_Click(object sender, EventArgs e)
		{
			Pick.AllocatePackageLabels();
		}

		void CancelPackageLabels_Click(object sender, EventArgs e)
		{
			var waitCursor = new DisposableAction(() => Cursor.Current = Cursors.WaitCursor, () => Cursor.Current = Cursors.Default);

			try
			{
				if (Env.Security.WhsPickingCancelPackageLabelAllocations.IsAllowed)
				{
					Pick.CancelPackageLabelAllocations();
				}
				else
				{
					Globals.Message.ShowError(WhsErrorTypes.NoSecurityRights.Message);
				}
			}
			finally
			{
				waitCursor.Dispose();
			}
		}

		void ChangeTaskPlanningStatusMenu_Click(object sender, EventArgs e)
		{
			var message = ObjectFactory.Get<IWhsTaskManagementService>().ChangeTaskPlanningStatus(Pick);
			if (!message.IsNullOrEmpty())
			{
				Globals.Message.ShowWarning(message);
			}
		}

