				e.ContinueToPrint = (ZFormModaliser.ShowDialogAndDispose(new DocketsLabelOptionForm(e.DocketsLabelControl)) == DialogResult.Yes) && e.DocketsLabelControl.Lines.NumberOfLabelsToPrint > 0;
